style.css:
@-moz-document url-prefix("chrome://newtab/"), url-prefix("https://"), url-prefix("http://") {
body::before {
    content: "";
    position: fixed;
    top: 10px;
    left: 10px;
    width: 45px;
    height: 14px;
    z-index: 999999;
    background: none;
  }

  body::after {
    content: "";
    position: fixed;
    top: 10px;
    left: 10px;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background-color: red;
    box-shadow: 15px 0 yellow, 30px 0 green;
    z-index: 999999;
  }
}
